	private static FixtureRecipe defaultGraphRecipe(ThemeOracleProfile profile, Supplier<Model> source) {
		return new FixtureRecipe(() -> fixture(source.get()), (metadata, data) -> {
			metadata.put("profile", profile.fixtureId());
			writeScope(metadata);
			metadata.put("statementCount", data.fixture().size());
		}, (metadata, model) -> {
			require(profile.fixtureId().equals(text(metadata, "profile")), "fixture profile differs");
			verifyScope(metadata.path("scope"));
			require(model.equals(source.get()), "fixture statements differ from profile");
			require(model.size() == longValue(metadata, "statementCount"), "fixture statement count differs");
		});
	}

